import time
import urllib.request
import urllib.error


class RateLimitError(Exception):
    """Raised when the API keeps returning HTTP 429 after retries."""
    pass


class ServerError(Exception):
    """Raised when the API keeps returning HTTP 5xx after retries."""
    pass


class ClientError(Exception):
    """Raised when the API returns HTTP 4xx (other than 429)."""
    pass


class ConnectionError(Exception):
    """Raised when a network error persists after retries."""
    pass


class APIClient:
    """A minimal HTTP API client built on urllib.request."""

    def __init__(self, base_url, timeout=10):
        self.base_url = base_url.rstrip("/")
        self.timeout = timeout

    def get(self, path):
        """GET base_url + path and return the response body as a string."""
        url = self.base_url + "/" + path.lstrip("/")

        # (attempt_number, sleep_before_this_attempt)
        # Attempt 0 runs immediately; later attempts sleep first.
        schedule = [(0, 0.0), (1, 0.5), (2, 1.0), (3, 2.0)]  # 429 backoff
        last_http_error = None

        # --- HTTP 429 handling: up to 4 total attempts (3 retries) ---
        for attempt, sleep_for in schedule:
            if sleep_for:
                time.sleep(sleep_for)
            try:
                return self._do_get(url)
            except urllib.error.HTTPError as e:
                if e.code == 429:
                    last_http_error = e
                    continue
                # Not a 429: fall through to general error handling.
                return self._handle_other_errors(url, e)
        raise RateLimitError(
            "Still rate-limited (HTTP 429) after 3 retries: {}".format(last_http_error)
        )

    def _do_get(self, url):
        """Perform a single GET request; return body as str."""
        req = urllib.request.Request(url, method="GET")
        with urllib.request.urlopen(req, timeout=self.timeout) as resp:
            return resp.read().decode("utf-8")

    def _handle_other_errors(self, url, e):
        """Handle non-429 HTTP errors and network errors with retry policy."""
        if isinstance(e, urllib.error.HTTPError):
            if 500 <= e.code < 600:
                # HTTP 5xx: retry once after 1s.
                time.sleep(1.0)
                try:
                    return self._do_get(url)
                except urllib.error.HTTPError as e2:
                    if 500 <= e2.code < 600:
                        raise ServerError(
                            "Server error (HTTP {}) persisted after retry: {}".format(
                                e2.code, e2
                            )
